        const inbox = await window.cth.hiveInbox(agentId);
        if (alive) setMessages(inbox);
      } catch { /* keep last good state */ }
    };
    load();
    const timer = setInterval(load, 3000);
    return () => { alive = false; clearInterval(timer); };
